from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_SECTION
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT = Path(__file__).resolve().parent
OUT_GUIDE = ROOT / 'Finance Module Process Guide.docx'
OUT_FLOWS = ROOT / 'Finance Module Flowcharts.docx'
BLUE = '17365D'; TEAL = '0F6B78'; LIGHT = 'EAF2F8'; GREEN = 'E2F0D9'; AMBER = 'FFF2CC'; RED = 'FCE4D6'; GRAY = 'F2F2F2'; WHITE = 'FFFFFF'

def shade(cell, color):
    tcPr = cell._tc.get_or_add_tcPr(); shd = OxmlElement('w:shd'); shd.set(qn('w:fill'), color); tcPr.append(shd)
def border(cell, color='B7C9D6'):
    tcPr = cell._tc.get_or_add_tcPr(); b = OxmlElement('w:tcBorders')
    for e in ('top','left','bottom','right'):
        x=OxmlElement(f'w:{e}'); x.set(qn('w:val'),'single'); x.set(qn('w:sz'),'8'); x.set(qn('w:color'),color); b.append(x)
    tcPr.append(b)
def set_cell(cell, text, fill=None, bold=False, color=None, size=9):
    cell.text=''; p=cell.paragraphs[0]; p.paragraph_format.space_after=Pt(0)
    r=p.add_run(text); r.bold=bold; r.font.size=Pt(size); r.font.name='Aptos';
    if color: r.font.color.rgb=RGBColor.from_string(color)
    if fill: shade(cell,fill)
    border(cell); cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
def setup(doc, landscape=False):
    sec=doc.sections[0]; sec.top_margin=Inches(.65); sec.bottom_margin=Inches(.65); sec.left_margin=Inches(.7); sec.right_margin=Inches(.7)
    if landscape: sec.orientation=1; sec.page_width,sec.page_height=sec.page_height,sec.page_width
    normal=doc.styles['Normal']; normal.font.name='Aptos'; normal.font.size=Pt(9); normal.paragraph_format.space_after=Pt(5)
    for name,size,col in [('Title',25,BLUE),('Heading 1',17,BLUE),('Heading 2',13,TEAL),('Heading 3',11,BLUE)]:
        s=doc.styles[name]; s.font.name='Aptos Display' if name=='Title' else 'Aptos'; s.font.size=Pt(size); s.font.bold=True; s.font.color.rgb=RGBColor.from_string(col)
        s.paragraph_format.space_before=Pt(13); s.paragraph_format.space_after=Pt(6)
    footer=sec.footer.paragraphs[0]; footer.alignment=WD_ALIGN_PARAGRAPH.CENTER
    rr=footer.add_run('Finance Module Implementation Guide  |  Current codebase review  |  November 2026'); rr.font.size=Pt(8); rr.font.color.rgb=RGBColor.from_string('666666')
def title(doc, text, subtitle):
    p=doc.add_paragraph(style='Title'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run(text)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(subtitle); r.italic=True; r.font.size=Pt(12); r.font.color.rgb=RGBColor.from_string(TEAL)
    doc.add_paragraph('Evidence base: routes, middleware, utilities, migrations, browser scripts, and available finance/security tests in the current repository.', style='Subtitle')
def add_note(doc, label, text, fill=LIGHT):
    t=doc.add_table(rows=1, cols=1); t.alignment=WD_TABLE_ALIGNMENT.CENTER; c=t.cell(0,0); set_cell(c, f'{label}: {text}',fill,True if label in ('IMPORTANT','KNOWN LIMITATION','POTENTIAL BUG') else False,size=9)
def table(doc, headers, rows, widths=None):
    t=doc.add_table(rows=1,cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for i,h in enumerate(headers): set_cell(t.rows[0].cells[i],h,BLUE,True,WHITE)
    for row in rows:
        cells=t.add_row().cells
        for i,v in enumerate(row): set_cell(cells[i],str(v), LIGHT if len(t.rows)%2==0 else WHITE)
    if widths:
        for row in t.rows:
            for i,w in enumerate(widths): row.cells[i].width=Inches(w)
    doc.add_paragraph('')
def code(doc, pathline, text):
    p=doc.add_paragraph(); r=p.add_run(pathline); r.bold=True; r.font.color.rgb=RGBColor.from_string(TEAL); r.font.size=Pt(9)
    p=doc.add_paragraph(); p.paragraph_format.left_indent=Inches(.18); p.paragraph_format.right_indent=Inches(.18); p.paragraph_format.space_after=Pt(7)
    r=p.add_run(text.strip()); r.font.name='Consolas'; r.font.size=Pt(7.2); r.font.color.rgb=RGBColor.from_string('202020')
    pPr=p._p.get_or_add_pPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),'F5F7F9'); pPr.append(shd)
def bullets(doc, items):
    for x in items: doc.add_paragraph(x, style='List Bullet')
def heading(doc, h, level=1): doc.add_heading(h, level=level)

def guide():
    d=Document(); setup(d); title(d,'Finance Module Process Guide','How money, records, inventory, reporting, and PayMongo behavior actually connect')
    add_note(d,'READ THIS FIRST','This is an implementation guide, not a statement of accounting compliance. “Confirmed” means supported by current code. Items marked Known limitation or Potential bug are deliberate findings from that code.')
    heading(d,'Executive map')
    d.add_paragraph('Finance is split across two areas. The Finance API owns manual balance receipts, product sales, cash closing, expenses, reporting, exports, and ledger actions. Appointment routes own customer PayMongo checkout, payment confirmation, webhooks, cancellation handling, and PayMongo refunds.')
    table(d,['Area','Primary code','What it persists'],[
      ('Finance operations','routes/finance.js','payments, product_sale_details, inventory transactions, expenses, cash closings, reversal and edit audit rows'),
      ('Online deposits','routes/appointments.js','paymongo_checkout_sessions, appointments, reservation payment ledger rows'),
      ('Access control','middleware/auth.js; utils/privilegedMfa.js','session role and time-limited MFA assurance'),
      ('Rules','utils/financeRules.js','deposits reduce balance; no-show deposits count as revenue'),
      ('UI','public/js/finance-*.js','fetches protected API and presents receipts/reports/forms')])
    heading(d,'Roles and permitted paths')
    table(d,['Actor','Can do','Cannot do through Finance API'],[
      ('finance_officer','All /api/finance endpoints after active-session and MFA checks: entries, sales, reversals, expenses, closing, reports and exports.','Does not gain appointment-management authority merely from this route.'),
      ('admin','Same Finance API access; separate appointment routes also give administrative actions.','Must still meet privileged MFA assurance.'),
      ('client','Starts PayMongo checkout, confirms own checkout, requests/carries cancellation flow.','Cannot call Finance API.'),
      ('other staff','No Finance API access.','Cannot bypass role middleware from UI.')])
    code(d,'routes/finance.js:20','router.use(requireRole(\'finance_officer\', \'admin\'));')
    code(d,'utils/financeRules.js:1-4','const DEPOSIT_DEDUCTED_FROM_PRICE = true;\nconst NO_SHOW_DEPOSIT_IS_INCOME = true;\nmodule.exports = { DEPOSIT_DEDUCTED_FROM_PRICE, NO_SHOW_DEPOSIT_IS_INCOME };')
    d.add_paragraph('The first flag means posted reservation deposits count toward an appointment’s booked price when Finance computes an outstanding balance. The second means a posted deposit is included in sales only for no-shows or explicitly marked forfeited cancelled appointments.')

    heading(d,'Data model and status vocabulary')
    table(d,['Record','Meaning and relationships'],[
      ('payments','One ledger row per reservation, balance receipt, or product sale. Status is posted, refunded, or reversed. Reservation is tied to an appointment; product sale has no appointment.'),
      ('paymongo_checkout_sessions','Checkout snapshot and lifecycle: pending, paid, failed, expired, consumed, refunded. Stores amount in centavos, live/test mode, reference, and PayMongo payment ID.'),
      ('product_sale_details','One detail record links product, quantity, retained name/unit price, and idempotency request_key to a product_sale payment.'),
      ('cash_closings','One immutable close per business date; expected cash, counted cash, variance, closer.'),
      ('expenses and expense_edit_history','Operational expense with soft-void fields, and audit snapshots for edits.'),
      ('payment_reversals','One audit reason/reverser per reversed ledger payment.'),
      ('inventory_products and inventory_transactions','Stock is deducted for a sale; reversal adds stock back and writes a new inventory transaction.')])
    add_note(d,'IMPORTANT','Appointment payment_status is not the complete payment ledger. It chiefly follows the reservation/deposit lifecycle. A completed appointment may still have a balance receivable; Finance calculates this from booked_service_price minus posted ledger payments.')

    heading(d,'Process 1 Online reservation deposit through PayMongo')
    d.add_paragraph('The customer-facing appointment route creates a local pending checkout session, asks PayMongo for a checkout, and returns a hosted checkout URL. The PayMongo payment is later established by either the customer confirmation route or the signed webhook. Only appointment creation writes the reservation payment into the Finance ledger.')
    table(d,['Step','Frontend / API / database movement','Controls and result'],[
      ('1 Create checkout','Client posts appointment draft to POST /api/appointments/paymongo/checkout-session. Backend validates account/demo restrictions and creates a pending snapshot before/around PayMongo checkout creation.','The local amount and line items are later compared to PayMongo data.'),
      ('2 Pay externally','Customer uses PayMongo hosted page.','PayMongo is the payment processor; the Finance manual /payments route is not used.'),
      ('3 Establish paid state','POST /paymongo/confirm can recover from PayMongo; POST /paymongo/webhook receives PayMongo event using raw body.','Signature, timestamp, reference, mode, currency, payment status, and amount/line sum are checked.'),
      ('4 Make appointment','createAppointmentFromPaidCheckout locks availability, inserts confirmed appointment, inserts posted reservation payment, then marks checkout consumed.','Database transaction and uniqueness guard protect duplicate reservation ledger rows.'),
      ('5 Finance reporting','Finance reads the reservation payment. The deposit offsets balance; it becomes sales only when retained under configured rules.','Normal refundable deposits are cash collected but not sales-earned in the sales query.')])
    code(d,'index.js:36; routes/appointments.js:2966','app.use(\'/api/appointments/paymongo/webhook\', express.raw({ type: \'application/json\' }));\n// Raw bytes are retained before express.json so the HMAC can be verified.\nrouter.post(\'/paymongo/webhook\', async (req, res) => {\n  const config = getPayMongoConfig();\n  if (!config) return res.status(503).json({ error: \'PayMongo is not configured.\' });\n  if (!verifyPayMongoWebhookSignature(req.get(\'Paymongo-Signature\'), req.body, config)) {\n    return res.status(400).json({ error: \'Invalid PayMongo webhook signature.\' });\n  }\n  // validates event, local checkout, paid payment, amount and then consumes it idempotently\n});')
    code(d,'utils/paymongoWebhookSecurity.js:5-49','function verifyPayMongoWebhookSignature(signatureHeader, rawBody, config, nowSeconds = Math.floor(Date.now() / 1000)) {\n  if (typeof signatureHeader !== \'string\' || !Buffer.isBuffer(rawBody) || !config || !config.webhookSecret) return false;\n  const fields = {};\n  for (const part of signatureHeader.split(\',\')) {\n    const separator = part.trim().indexOf(\'=\');\n    if (separator <= 0) return false;\n    const name = part.trim().slice(0, separator).trim();\n    const value = part.trim().slice(separator + 1).trim();\n    if (![\'t\', \'te\', \'li\'].includes(name) || Object.hasOwn(fields, name)) return false;\n    fields[name] = value;\n  }\n  if (!/^\\d+$/.test(fields.t || \'\') || Math.abs(nowSeconds - Number(fields.t)) > 300) return false;\n  const supplied = fields[config.isLive ? \'li\' : \'te\'];\n  if (!/^[a-f\\d]{64}$/i.test(supplied || \'\')) return false;\n  const expected = createHmac(\'sha256\', config.webhookSecret)\n    .update(Buffer.concat([Buffer.from(`${fields.t}.`), rawBody])).digest();\n  const actual = Buffer.from(supplied, \'hex\');\n  return actual.length === expected.length && timingSafeEqual(actual, expected);\n}')
    bullets(d,['A delayed client confirmation is not automatically a failure: recovery queries PayMongo and verifies paid status before allowing consumption.','A duplicate webhook for a consumed checkout is treated idempotently: it backfills payment identifiers/method where needed instead of making a second appointment.','A valid but unmatched webhook is logged and returns success (HTTP 200), preventing repeated delivery but leaving it for investigation; no Finance alert is created.'])
    add_note(d,'POTENTIAL BUG','The confirmation path’s non-PHP currency rejection message describes an appointment-time problem, not a currency problem. The guard exists; its displayed explanation is misleading.')

    heading(d,'Process 2 Deposits, completed-service balances, and manual receipts')
    d.add_paragraph('Finance can post only a balance payment manually. Reservation payments are intentionally reserved for checkout, and product sales must use their dedicated atomic sale route. A balance payment can only target a completed, non-demo appointment and cannot exceed the calculated outstanding amount.')
    code(d,'routes/finance.js:835-862 (complete manual receipt handler)','router.post(\'/payments\', endpoint(async (req, res) => {\n  const body = req.body || {};\n  if (!PAYMENT_TYPES.includes(body.payment_type)) throw new ApiError(400, \'Invalid payment type.\');\n  if (!METHODS.includes(body.method)) throw new ApiError(400, \'Invalid payment method.\');\n  if (body.payment_type === \'product_sale\') throw new ApiError(400, \'Use the Record Sale form so the inventory deduction and payment are recorded together.\');\n  const amount = amountValue(body.amount);\n  const appointmentId = body.appointment_id == null ? null : idValue(body.appointment_id, \'Appointment ID\');\n  if (body.payment_type === \'balance\' && !appointmentId) throw new ApiError(400, \'Balance payments require an appointment.\');\n  if (body.payment_type === \'reservation\') throw new ApiError(400, \'Reservation payments are recorded during checkout.\');\n  const result = await db.transaction(async (client) => {\n    if (body.method === \'cash\') await lockCurrentCashBusinessDateIfOpen(client);\n    const appointment = await client.query(`SELECT booked_service_price, is_demo FROM appointments WHERE appointment_id = $1 AND appointment_status = \'completed\' FOR UPDATE`, [appointmentId]);\n    if (!appointment.rows.length) throw new ApiError(404, \'Completed appointment not found.\');\n    if (appointment.rows[0].is_demo) throw new ApiError(409, \'Payments are disabled for synthetic survey appointments.\');\n    const paid = await client.query(`SELECT COALESCE(SUM(amount), 0) AS paid FROM payments WHERE appointment_id = $1 AND status = \'posted\' AND ($2::boolean OR payment_type <> \'reservation\')`, [appointmentId, DEPOSIT_DEDUCTED_FROM_PRICE]);\n    const outstanding = Math.max(0, Number(appointment.rows[0].booked_service_price) - Number(paid.rows[0].paid));\n    if (amount > outstanding) throw new ApiError(400, `Payment exceeds the outstanding balance of ${outstanding.toFixed(2)}.`);\n    return client.query(`INSERT INTO payments (appointment_id, payment_type, amount, method, reference_no, note, recorded_by) VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING *`, [appointmentId, body.payment_type, amount, body.method, null, null, req.session.userId || null]);\n  });\n  res.status(201).json(result.rows[0]);\n}));')
    add_note(d,'KNOWN LIMITATION','The manual balance form accepts method “paymongo” as a label, but this endpoint does not call PayMongo or verify an external payment. It simply posts a local ledger row. PayMongo verification belongs to appointment checkout routes.')

    heading(d,'Process 3 Product sales and inventory integrity')
    d.add_paragraph('POST /api/finance/product-sales makes a receipt, detail row, stock change, and inventory movement in one database transaction. It requires a UUID request key. That key provides safe retry behavior: same payload returns the existing sale; changed payload with the same key returns conflict.')
    code(d,'routes/finance.js:865-955 (key transaction operations)','await client.query(\'SELECT pg_advisory_xact_lock(hashtext($1))\', [`finance-sale:${requestKey}`]);\nconst duplicate = await client.query(`SELECT payment.payment_id, detail.product_id, detail.quantity, detail.unit_price\n  FROM product_sale_details detail JOIN payments payment ON payment.payment_id = detail.payment_id\n  WHERE detail.request_key = $1`, [requestKey]);\nif (duplicate.rows.length) {\n  // exact same product, quantity, price, method, and reference => return replayed sale\n  // otherwise => HTTP 409; prevents one key representing two different sales\n}\nif (body.method === \'cash\') await lockCurrentCashBusinessDateIfOpen(client);\nconst productResult = await client.query(`SELECT product_id, product_name, stock_quantity FROM inventory_products WHERE product_id = $1 FOR UPDATE`, [productId]);\nif (!productResult.rows.length) throw new ApiError(404, \'Inventory product not found.\');\nif (previousStock < quantity) throw new ApiError(409, `Only ${previousStock} units remain in stock.`);\nawait client.query(`UPDATE inventory_products SET stock_quantity = $1, updated_at = NOW() WHERE product_id = $2`, [newStock, productId]);\nconst payment = await client.query(`INSERT INTO payments (appointment_id, payment_type, amount, method, reference_no, note, recorded_by) VALUES (NULL,\'product_sale\',$1,$2,$3,$4,$5) RETURNING *`, [total, body.method, reference, `Product sale: ${product.product_name}`, req.session.userId || null]);\nawait client.query(`INSERT INTO product_sale_details (payment_id, product_id, product_name, quantity, unit_price, request_key) VALUES ($1,$2,$3,$4,$5,$6)`, [payment.rows[0].payment_id, productId, product.product_name, quantity, unitPrice, requestKey]);\nawait client.query(`INSERT INTO inventory_transactions (product_id, product_name, transaction_type, quantity, previous_stock, new_stock, created_by, created_at) VALUES ($1,$2,\'Sale\',$3,$4,$5,$6,NOW())`, [productId, product.product_name, -quantity, previousStock, newStock, req.session.userId || null]);')
    d.add_paragraph('A product sale reversal requires its detail record. It changes the ledger to reversed, inserts payment_reversals, restores inventory, and logs “Sale Reversed.” A legacy product payment lacking detail is rejected because stock cannot be restored safely.')

    heading(d,'Process 4 Refunds, reversals, cancellations, and forfeiture')
    table(d,['Situation','Actual current behavior'],[
      ('Eligible online appointment cancellation','Appointment route calls PayMongo refund for full deposit, then marks reservation payment/ref checkout/appointment refunded if updates succeed.'),
      ('Late cancellation or no-show','Reservation payment remains posted. Cancellation gets [DEPOSIT_FORFEITED] note; configured reporting counts retained deposit as revenue.'),
      ('Finance cash reservation refund','Finance may mark a posted cash reservation refunded only when appointment is cancelled, not no-show/forfeited, cash date is open, and note supplied.'),
      ('Finance noncash reservation refund','Blocked with instruction that PayMongo refund must succeed; Finance cannot manually claim online money was refunded.'),
      ('Reversal','Ledger correction, not money movement. Inserts payment_reversals and sets status reversed; product sale additionally restores stock.'),
      ('Partial refund','Not implemented: no refund amount is accepted, and online/refund functions use full amount.')])
    add_note(d,'KNOWN LIMITATION','PayMongo is called before the transaction updates local ledger/session rows in refundAppointmentDeposit. If the external refund succeeds but a later database update fails, the database transaction rolls back while the customer has been refunded. This is a real external/local consistency gap; there is no outbox or compensating reconciliation job.')
    code(d,'routes/appointments.js:87-153 (refund state transition)','const refund = await refundPayMongoPayment({\n  paymentId: session.payment_id,\n  amountCents: session.amount_cents,\n  reason: \'requested_by_customer\',\n  config\n});\nif (!refund.ok) {\n  console.error(\'PayMongo refund failed for appointment\', appointmentId, refund.message);\n  return { refunded: false };\n}\nconst refundAuditNote = `PayMongo refund completed${refund.refundId ? ` (${refund.refundId})` : \'\'}`;\nconst paymentUpdate = await client.query(`\n  UPDATE payments\n  SET status = \'refunded\',\n      note = CONCAT_WS(E\'\\\\n\', NULLIF(note, \'\'), $1)\n  WHERE payment_id = $2 AND status = \'posted\'\n  RETURNING payment_id\n`, [refundAuditNote, paymentResult.rows[0].payment_id]);\nif (paymentUpdate.rows.length === 0) {\n  throw new Error(`PayMongo refunded appointment ${appointmentId}, but its posted reservation ledger entry could not be updated.`);\n}\nawait client.query(`UPDATE paymongo_checkout_sessions\n  SET status = \'refunded\', refunded_at = NOW(), updated_at = NOW()\n  WHERE reference_number = $1 AND status = \'consumed\'`, [session.reference_number]);\nawait client.query(`UPDATE appointments SET payment_status = \'refunded\' WHERE appointment_id = $1`, [appointmentId]);\nreturn { refunded: true };')
    add_note(d,'KNOWN LIMITATION','A reservation reversal does not send money to the customer and does not reset the consumed checkout-session state. The UI states this as a ledger-only correction; it can therefore diverge from PayMongo history if used as a substitute for refund.')

    heading(d,'Process 5 Cash closing and reconciliation')
    d.add_paragraph('Cash closing is by Asia/Manila business date. Expected cash is calculated from posted, non-demo cash payments created that date. A Finance user enters counted cash; the system stores the variance and alerts other Finance/Admin users when nonzero. A PostgreSQL advisory lock serializes attempts for the same date.')
    code(d,'routes/finance.js:120-143; 444 onward','async function lockCashBusinessDate(client, businessDate) {\n  await client.query(\'SELECT pg_advisory_xact_lock(hashtext($1))\', [`finance-cash-date:${businessDate}`]);\n}\nasync function assertBusinessDateOpen(client, businessDate, recordType = \'Cash receipts\') {\n  await lockCashBusinessDate(client, businessDate);\n  const closing = await client.query(\'SELECT 1 FROM cash_closings WHERE business_date = $1::date\', [businessDate]);\n  if (closing.rows.length) throw new ApiError(409, `Cash closing for ${businessDate} is already recorded. ${recordType} for this date are closed.`);\n}\n// closing POST locks date, recomputes expected cash, inserts cash_closings ON CONFLICT DO NOTHING, and returns 409 if already closed.')
    add_note(d,'KNOWN LIMITATION','Closing blocks new cash receipts and expense records for that business date, but it does not model how expenses were paid. Reports explicitly warn that they are mixed operational metrics, not a complete cash-flow statement. Noncash changes and appointment changes can still affect other reports after a close.')

    heading(d,'Process 6 Expenses, purchase suggestions, and audit trail')
    d.add_paragraph('Finance creates an expense after validating date, category, amount, description, supplier, and reference. Editing locks the current record and both the old/new business dates, updates it, and writes before/after JSON to expense_edit_history. Void is a soft void with reason and actor; reports exclude voided records. Inventory purchase suggestions turn eligible unlinked procurement records into an Inventory & Supplies expense, using a transaction so a purchase cannot be linked twice.')
    code(d,'routes/finance.js:1233-1293; 1295-1315 (edit and soft-void operations)','// Edit route locks the expense, locks its prior and requested business dates, then:\nawait client.query(`UPDATE expenses SET expense_date = $1, category = $2, description = $3,\n  amount = $4, supplier = $5, reference_no = $6, updated_at = NOW()\n  WHERE expense_id = $7`, [body.expense_date, body.category, body.description, body.amount, body.supplier, body.reference_no, expenseId]);\nawait client.query(`INSERT INTO expense_edit_history (expense_id, edited_by, previous_values, updated_values)\n  VALUES ($1,$2,$3::jsonb,$4::jsonb)`, [expenseId, req.session.userId || null, JSON.stringify(previous), JSON.stringify(updated)]);\n// Void route: no deletion.\nawait client.query(`UPDATE expenses SET voided_at = NOW(), voided_by = $1, void_reason = $2, updated_at = NOW()\n  WHERE expense_id = $3 AND voided_at IS NULL`, [req.session.userId || null, reason, expenseId]);')
    table(d,['Outcome','Safeguard'],[
      ('Attempt to add/edit/void after close','409 from assertBusinessDateOpen.'),('Same purchase suggestion submitted twice','Second request returns existing linked expense with replayed true.'),('Migration missing','Some finance schema helpers map missing tables to 503 with migration guidance.'),('Expense deletion','No hard-delete route; void preserves evidence.')])

    heading(d,'Process 7 Dashboard, revenue, ledger, reporting, and exports')
    d.add_paragraph('The dashboard uses summary, monthly, daily, payment-method/type, service/category, deposits, expenses, activity, receivables, and report endpoints. Report calculations separate “sales earned” from “cash collected.” Sales earned contains completed service price, product sales, and retained deposits. Cash collected sums posted ledger payments by receipt date. Expenses use expense_date and exclude voids. Net income shown is total collected less expenses and is explicitly an operational metric.')
    code(d,'routes/finance.js:reportData and report endpoint around 180-260; 1319','// Sales-earned union includes completed booked service prices, product-sale receipts,\n// and reservation deposits only when retained by NO_SHOW_DEPOSIT_IS_INCOME rules.\nconst [sales, collected, expenses] = await Promise.all([\n  db.query(`SELECT COALESCE(SUM(amount), 0)::float8 AS amount FROM (${salesUnion}) sale_rows`, [from, to, NO_SHOW_DEPOSIT_IS_INCOME]),\n  db.query(`SELECT COALESCE(SUM(amount), 0)::float8 AS amount FROM payments p\n    LEFT JOIN appointments a ON a.appointment_id = p.appointment_id\n    WHERE p.status = \'posted\' AND (a.is_demo = FALSE OR a.appointment_id IS NULL)\n      AND (p.created_at AT TIME ZONE \'Asia/Manila\')::date BETWEEN $1 AND $2`, [from, to]),\n  db.query(`SELECT COALESCE(SUM(amount), 0)::float8 AS amount FROM expenses\n    WHERE voided_at IS NULL AND expense_date BETWEEN $1 AND $2`, [from, to])\n]);\nconst netIncome = Number(collected.rows[0].amount) - Number(expenses.rows[0].amount);\n// Endpoint serializes these values with a warning that this is mixed operational reporting.')
    table(d,['Report item','Source and caveat'],[
      ('Receivables','Completed non-demo appointment booked price less posted payments; deposits reduce balance because rule flag is true.'),('Sales earned','Completed appointment booked price + posted product sales + retained deposit conditions.'),('Cash collected','All posted non-demo payments by Manila receipt date; revenue recognition differs from this.'),('Export workbook','Financial summary, sales detail, payment ledger/references, expense register, daily reconciliation and other sheets; generated by ExcelJS.'),('CSV/XLSX','GET export.xlsx / export.csv supports selected report types; POST export-report.xlsx makes complete workbook.')])
    add_note(d,'KNOWN LIMITATION','Refund entries do not have a separate refund-event date in the ledger exports, and expense payment method/settlement is not stored. These facts limit formal cash-flow and period-correct refund analysis.')

    heading(d,'Edge cases and evidence-based assessment')
    table(d,['Scenario','Result','Assessment'],[
      ('Webhook replay','Consumed checkout updates/backfills rather than creates duplicate appointment.','Successfully handled.'),('Webhook signature stale, malformed, duplicate field, wrong mode signature','Rejected before processing.','Successfully handled; signature unit tests passed.'),('Paid amount or line-item mismatch','Confirmation/webhook does not consume checkout.','Successfully handled.'),('Checkout paid after appointment time/slot lost','Attempted automatic PayMongo refund and paid/late or unavailable state handling.','Handled workflow, subject to external API/database consistency limitation.'),('Duplicate product sale request','Same payload replayed; different payload same key conflict.','Successfully handled.'),('Oversold product','Locked stock check rejects sale.','Successfully handled.'),('Balance overpayment','Locked appointment + posted-payment sum rejects above outstanding.','Successfully handled.'),('Closed cash date modification','Cash receipt/expense-related action gets 409.','Successfully handled within its scope.'),('Unmatched valid webhook','HTTP 200 + warning; no automatic reconciliation record/alert.','Known operational gap.'),('PayMongo refund succeeds, local update fails','External money and local status can diverge.','Potential consistency bug.'),('Partial refund request','No supported path.','Known missing feature.'),('Full webhook integration test in this review','Could not reach configured Render PostgreSQL host; retry test returned 500 due DNS.','Environment limitation; not proof of code behavior.')])

    heading(d,'File and line reference index')
    table(d,['File','Relevant lines / responsibility'],[
      ('index.js','36 raw webhook body before JSON parser; 297 mounts /api/finance; finance page restrictions near 247.'),('routes/finance.js','20 role gate; 120-147 closing locks; 368-489 close/history; 824 receivables; 835 balance receipt; 865 product sale; 965 refund; 1015 reversal; 1126-1315 expenses; 1319 report; 2516-2545 exports.'),('routes/appointments.js','28 payment method mapping; 57 checkout refund; 87 appointment-deposit refund; 1822 appointment creation; 1896 payment recovery; 2689 checkout create; 2826 confirm; 2966 webhook.'),('utils/paymongoWebhookSecurity.js','5-49 timestamped HMAC and timing-safe comparison.'),('utils/paymongoConfig.js','PayMongo key/environment configuration validation.'),('utils/financeRules.js','1-4 active deposit accounting flags.'),('middleware/auth.js; utils/privilegedMfa.js','requireRole, active session, privileged role MFA assurance.'),('migrations/021-finance.js; 030-033; 047-*','Finance base tables; reversals; product sales/purchases; cash closing; expense audit; checkout enhancements.')])
    heading(d,'How the browser connects')
    d.add_paragraph('The Finance pages use finance-common.js fetchJson with same-origin credentials. finance-dashboard.js loads the dashboard/read endpoints; finance-transactions.js posts balance payments, product sales, refunds, reversals and opens receipt views; finance-expenses.js manages expense actions/history; finance-reports.js calls report and export endpoints. Server-side role/MFA controls remain authoritative; hiding a button is not the security boundary.')
    d.add_paragraph('End of guide. Source descriptions reflect the repository inspected on 11 November 2026.', style='Subtitle')
    d.save(OUT_GUIDE)

def flow_node(d, text, kind='process'):
    color={'process':LIGHT,'decision':AMBER,'success':GREEN,'risk':RED,'data':GRAY}[kind]
    t=d.add_table(rows=1,cols=1); t.alignment=WD_TABLE_ALIGNMENT.CENTER; c=t.cell(0,0); set_cell(c,text,color,True if kind in ('decision','risk') else False,size=10)
    p=d.add_paragraph('↓'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(2); p.paragraph_format.space_before=Pt(2)
def branch(d,left,right):
    t=d.add_table(rows=1,cols=2); t.alignment=WD_TABLE_ALIGNMENT.CENTER
    set_cell(t.cell(0,0),left, GREEN if left.startswith('YES') else LIGHT, left.startswith('YES'), size=9)
    set_cell(t.cell(0,1),right, RED if right.startswith('NO') else AMBER, right.startswith('NO'), size=9)
    p=d.add_paragraph('↓'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(2)
def flows():
    d=Document(); setup(d, landscape=True); title(d,'Finance Module Flowcharts','Detailed implementation pathways, decisions, alternatives, exceptions, and cross-module handoffs')
    d.add_paragraph('Legend: blue = process/data, yellow = decision, green = confirmed success, red = failure/risk. These diagrams describe current code rather than desired future behavior.')
    flows_data=[
      ('1 Online Reservation Deposit and PayMongo',[('Client starts checkout → POST /appointments/paymongo/checkout-session → pending paymongo_checkout_sessions snapshot + PayMongo hosted checkout URL','process'),('Customer pays on PayMongo; either client calls /confirm or PayMongo calls signed /webhook','data'),('Decision: valid account/config/signature (webhook), matching local reference/mode/PHP/paid status/centavos?','decision'),('YES → lock local checkout. Create appointment only if clinic slot still available; insert reservation payment; checkout = consumed. Duplicate consumed webhook only backfills IDs/method.','NO → reject invalid request, leave checkout pending/unconsumed, or log valid unmatched event and return 200.','branch'),('Decision: appointment time passed or slot unavailable after payment?','decision'),('YES → attempt full PayMongo refund; checkout becomes refunded only if local updates succeed.','NO → confirmed appointment + posted reservation ledger row + Finance can display deposit.','branch')]),
      ('2 Completed Appointment Balance Receipt',[('Finance officer/admin opens receivables → GET /finance/receivables','process'),('POST /finance/payments with payment_type=balance, appointment, amount, method','data'),('Decision: valid amount/method; completed non-demo appointment; amount ≤ booked price minus posted payments?','decision'),('YES → if cash, require current Manila cash date open; lock appointment; insert posted payment ledger row.','NO → 400/404/409. Reservation requests directed to checkout; product sales directed to sale route.','branch'),('Finance dashboards/reports and receipt endpoints read the new posted ledger row','success')]),
      ('3 Product Sale Inventory and Reversal',[('Finance posts UUID request_key + product + quantity + unit price + method → /finance/product-sales','process'),('Transaction acquires advisory request-key lock; looks for product_sale_details duplicate','data'),('Decision: existing request_key?','decision'),('YES exact details → return same sale with replayed=true. Different details → HTTP 409.','NO → for cash require open date; lock inventory product FOR UPDATE.','branch'),('Decision: product exists and stock ≥ quantity?','decision'),('YES → decrement stock; insert product_sale payment; insert detail; insert inventory Sale movement; commit together.','NO → 404 or 409; transaction rolls back, so no receipt or stock change.','branch'),('Later reversal: payment_reversals row + ledger reversed + stock restored + “Sale Reversed” movement; legacy sale without detail blocked.','success')]),
      ('4 Cancellation Refund and Deposit Forfeiture',[('Appointment cancellation/review route evaluates the cancellation outcome','process'),('Decision: paid online deposit and eligible for refund?','decision'),('YES → refundAppointmentDeposit locks appointment/session/ledger; calls PayMongo full refund; updates payment=refunded, checkout=refunded, appointment payment_status=refunded.','NO → late cancellation/no-show retains posted deposit; cancellation writes [DEPOSIT_FORFEITED] note.','branch'),('Finance sales calculation includes retained deposit only for no-show (active rule) or cancelled appointment bearing that marker.','success'),('Exception: PayMongo refund can succeed before later DB update fails → external refund may not match local records.','risk')]),
      ('5 Cash Closing and Expense Control',[('Finance opens cash close for Manila business date → system totals posted non-demo cash payments created that date','process'),('POST /finance/cash-closing with counted cash','data'),('Transaction advisory-locks date; recomputes expected cash; attempts one cash_closings insert','process'),('Decision: already closed / future date / invalid amount?','decision'),('YES → 409/400; no duplicate close.','NO → save expected, actual, variance, closed_by; notify other Finance/Admin users if variance nonzero.','branch'),('After closing, cash receipts and expense changes for the date call assertBusinessDateOpen and are rejected. Expense settlement method itself is not modeled.','risk')]),
      ('6 Expense, Purchase Suggestion, Reports and Export',[('Finance creates/edits/voids expense: validation → date lock → expense row; edits create JSON audit history; void is soft void with reason.','process'),('Inventory purchase suggestion creates one Inventory & Supplies expense and links purchase record in same transaction','data'),('Decision: purchase already linked / expense date closed / migration table absent?','decision'),('YES linked → return existing expense replay; closed → 409; missing feature schema may return 503 migration guidance.','NO → create/link active expense; reports include it until soft void.','branch'),('Dashboard/report combines sales earned, cash collected, receivables, expenses and ledgers. Export creates CSV/XLSX via ExcelJS.','success'),('Caveat: net income is total collected less expenses, not a complete cash-flow/accounting statement; refunds lack a separate event date.','risk')])]
    for n,(name,nodes) in enumerate(flows_data):
        heading(d,name)
        for node in nodes:
            if node[-1]=='branch': branch(d,node[0],node[1])
            else: flow_node(d,node[0],node[1])
        if n < len(flows_data)-1: d.add_page_break()
    heading(d,'Cross process connections')
    table(d,['From','To','Connection'],[
      ('PayMongo checkout','Finance ledger','Appointment creation inserts posted reservation payment; not checkout creation alone.'),('Reservation deposit','Receivables','Active rule subtracts posted deposit from booked service price.'),('Product sale','Inventory','Sale and stock deduction share one transaction; reversal restores stock.'),('Cash receipt / expense','Cash close','Current-business-date receipt/expense changes require date still open.'),('Cancellation','Revenue','Forfeited/no-show deposit is counted in sales-earned logic; refunded deposit is not.')])
    d.save(OUT_FLOWS)

if __name__ == '__main__':
    guide(); flows(); print(OUT_GUIDE); print(OUT_FLOWS)
